 const f=await preparedClone(t,{cloneResultsOnly:true}),before=await api.readAutomaticClone(ID,actor),originalProject=before.request.base.project_archive_id;assert.equal(typeof originalProject,'string');const original=await api.getSiteArchiveMetadata(ID,originalProject,OWNER);assert.equal(original.file.role,'project_archive');assert.equal(f.plan.delivery_mode,'results-only');assert.equal(f.plan.project_archive,null);assert.equal(f.plan.release_manifest.project_archive,null);assert.equal(f.sql.prepare("SELECT count(*) n FROM app_state WHERE key LIKE 'site_archive_v1:%' AND json_extract(value,'$.archive.file.role')='project_archive'").get().n,1);const approved=await api.approvePostVideoPreparation(ID,{plan_id:f.plan.plan_id,expected_version:f.plan.version,confirmation:true},actor);assert.equal(approved.job.facts.release_package_ready,true);assert.equal(api.completedProductionDelivery(approved.job),true);assert.deepEqual(await api.getSiteArchiveMetadata(ID,originalProject,OWNER),original);assert.equal(approved.job.publication_reports.length,0);
