function changeStaged(f,kind,change){const key=kind==='draft'?'local_review_draft_v1:'+ID+':'+f.draft.local_draft_id:kind==='request'?'automatic_local_clone_v1:'+ID+':'+f.cloneRequest.id:'site_archive_v1:'+f.stagedVideoArchive,row=f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(key);assert.ok(row,key);const value=JSON.parse(row.value);change(value);if(kind==='draft')value.request_hash=sha(JSON.stringify(value.request,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x));f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(value),key);}
async function readStagedWithoutWrites(f,readActor=actor){const before=stagedSnapshot(f);try{return(await api.readAutomaticClone(ID,readActor)).current_staged_result;}finally{assert.equal(stagedSnapshot(f),before,'staged projection must not write SQLite or R2');}}
for(const mode of ['auto','node'])test(mode+' current staged clone exposes its confirmed real video while ZIP uploads, without returning or approving it',async t=>{
 const f=await cloneReturned(t,null,{preview:true,mode,stagingOnly:true}),view=await readStagedWithoutWrites(f);assert.ok(view);assert.equal(view.id,ID);assert.equal(view.request_id,f.cloneRequest.id);assert.equal(view.local_draft_id,f.draft.local_draft_id);assert.deepEqual(view.binding,f.cloneRequest.binding);assert.equal(view.status,'staging');assert.deepEqual(view.video,{site_archive_id:f.stagedVideoArchive,sha256:f.request.video.sha256,size_bytes:f.video.length,duration_seconds:f.request.video.duration,url:'/api/site-archive?id='+encodeURIComponent(ID)+'&archive='+f.stagedVideoArchive});assert.equal(view.technical_archive.status,'uploading');assert.equal(view.technical_archive.site_archive_id,f.stagedProjectArchive);assert.equal(view.technical_archive.sha256,f.request.project_archive.sha256);assert.equal(view.technical_archive.size_bytes,f.zip.length);assert.equal(view.technical_archive.part_count,1);assert.equal(view.technical_archive.uploaded_parts,undefined);for(const flag of ['warehouse_allowed','quality_approved','publication_authorized'])assert.equal(view[flag],false);assert.equal(view.human_review_pending,true);const after=await api.getJob(ID);assert.equal((await api.readAutomaticClone(ID,actor)).clone.stage,'audio_ready');assert.equal(api.automaticCloneWarehouseAllowed(after),false);assert.equal(after.milestones.filter(m=>m.node==='video').length,1);assert.equal(f.sql.prepare("SELECT count(*) n FROM production_reviews WHERE decision='automatic_clone_returned_v1'").get().n,0);assert.equal(after.publication_reports.length,0);
});
test('staged clone can truthfully report a not-started project archive while video is already confirmed',async t=>{const f=await cloneReturned(t,null,{stagingOnly:true,archiveStarted:false}),view=await readStagedWithoutWrites(f);assert.ok(view);assert.equal(view.technical_archive.status,'not_started');assert.equal(view.technical_archive.site_archive_id,undefined);assert.equal(view.technical_archive.sha256,f.request.project_archive.sha256);assert.equal(view.technical_archive.size_bytes,f.zip.length);assert.equal(view.technical_archive.uploaded_parts,undefined);});
const invalidStagedCases=[
 ['foreign draft owner','draft',d=>d.owner_id='SYNTHETIC-other-owner'],['foreign draft job','draft',d=>d.job_id='job_55555555-5555-4555-8555-555555555555'],['stale draft request','draft',d=>d.automatic_clone.request_id='acl_'+'0'.repeat(64)],['stale revision','draft',d=>d.binding.revision++],['stale epoch','draft',d=>d.binding.mode_epoch++],['stale contract','draft',d=>d.binding.contract_hash='0'.repeat(64)],['stale script','draft',d=>d.binding.script_hash='0'.repeat(64)],['wrong narration kind','draft',d=>d.request.voice.kind='ordinary-review'],['wrong owner voice marker','draft',d=>d.request.voice.owner_clone_used=false],['wrong draft audio','draft',d=>d.request.voice.audio_sha256='0'.repeat(64)],['wrong clone audio','draft',d=>d.automatic_clone.audio_sha256='0'.repeat(64)],['wrong first review','draft',d=>d.automatic_clone.first_review_id='SYNTHETIC-other-review'],['wrong first base','draft',d=>d.automatic_clone.base_id='SYNTHETIC-other-base'],['abandoned draft','draft',d=>d.status='abandoned'],['returned draft','draft',d=>d.status='returned'],['wrong request voice','request',r=>r.voice_id='SYNTHETIC-other-voice'],['wrong provider voice','request',r=>r.provider_result.voice_id='SYNTHETIC-other-voice'],['wrong provider audio','request',r=>r.provider_result.audio_sha256='0'.repeat(64)],['stale clone state','request',r=>r.status='awaiting_second_review'],['unconfirmed video','archive',a=>a.archive.status='uploading'],['sealed video','archive',a=>a.archive.status='sealed'],['wrong materialized SHA','archive',a=>a.archive.materialized_sha256='0'.repeat(64)],['foreign archive owner','archive',a=>a.owner_id='SYNTHETIC-other-owner']
];
for(const [label,kind,change]of invalidStagedCases)test('current staged clone rejects '+label+' without repairing any stored state',async t=>{const f=await cloneReturned(t,null,{stagingOnly:true});changeStaged(f,kind,change);assert.equal(await readStagedWithoutWrites(f),null);});
test('current staged clone rejects another owner and stale current guard without any writes',async t=>{const f=await cloneReturned(t,null,{stagingOnly:true});await assert.rejects(()=>readStagedWithoutWrites(f,{owner_id:'SYNTHETIC-other-owner'}));f.sql.prepare('UPDATE production_jobs SET updated_at=? WHERE id=?').run('2026-10-21T00:00:00Z',ID);assert.equal(await readStagedWithoutWrites(f),null);});
