const requestKey=p=>'automatic_local_clone_v1:'+ID+':'+p.id;
const savedRequest=(f,p)=>JSON.parse(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(requestKey(p)).value);
function putRequest(f,p){f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(p),requestKey(p));return p;}
test('real saved engine is frozen only at quote, and an unstarted queued request can refresh its expired catalog evidence without another owner approval',async t=>{const f=await first(t),initial=f.state.request,oldReviews=JSON.stringify(f.sql.prepare('SELECT * FROM production_reviews WHERE decision IN (\'approve\',\'automatic_clone_requested_v1\') ORDER BY id').all());assert.equal(initial.engine,null);assert.equal(api.AUTOMATIC_CLONE_VOICE.engine,undefined);let p=(await api.quoteAutomaticClone(ID,{request_id:initial.id,version:initial.version,quote:freshQuote()},actor)).request;assert.equal(p.engine,'elevenlabs');assert.equal(api.automaticCloneEngineBound(p),true);assert.equal(p.engine_binding.voice_response_sha256,p.quote.voice_response_sha256);p=putRequest(f,{...p,quote:{...p.quote,expires_at:'2020-01-01T00:00:00Z'}});p=(await api.quoteAutomaticClone(ID,{request_id:p.id,version:p.version,quote:{...freshQuote(),saved_default_engine:'starfish',voice_response_sha256:'6'.repeat(64)}},actor)).request;assert.equal(p.engine,'starfish');assert.equal(p.id,initial.id);assert.equal(p.first_review_id,initial.first_review_id);assert.equal(p.engine_binding.voice_response_sha256,'6'.repeat(64));assert.equal(JSON.stringify(f.sql.prepare('SELECT * FROM production_reviews WHERE decision IN (\'approve\',\'automatic_clone_requested_v1\') ORDER BY id').all()),oldReviews);});
