async function failedClone(t){const f=await first(t),{p,auth}=await started(f),u=(await api.blockAutomaticClone(ID,{request_id:p.id,version:p.version,lease_token:auth.lease_token,reason:'SYNTHETIC real tool parameter rejection; original output pending formal reconciliation'},actor)).request,proof=terminalFailure(u),r=await api.recordAutomaticCloneTerminalFailure(ID,{request_id:u.id,version:u.version,failure:proof},{trusted_owner_service:true});return{...f,original:p,unknown:u,proof,failed:r.request,body:{request_id:r.request.id,version:r.request.version,confirmed:true,terminal_failure_sha256:r.request.terminal_failure_sha256,owner_decision_id:'SYNTHETIC-owner-explicit-decision-1'}};}

test('confirmed terminal tool rejection waits for explicit owner retry; one linked request preserves original intent and re-quotes the current saved engine',async t=>{
 const f=await failedClone(t),before=f.protectedRows(),original=structuredClone(savedRequest(f,f.failed)),firstReviews=f.sql.prepare("SELECT * FROM production_reviews WHERE decision='approve' ORDER BY id").all();assert.equal(f.failed.status,'provider_failed');assert.equal(f.failed.provider_call_started,true);assert.equal(f.failed.provider_result,undefined);assert.equal(await api.nextAutomaticClone(),null,'a recorded terminal failure must not keep occupying provider_unknown reconciliation');assert.equal(f.state.request.id,original.id);
 await assert.rejects(()=>api.retryAutomaticClone(ID,f.body,{trusted_owner_service:true}),e=>e.status===403);await assert.rejects(()=>api.retryAutomaticClone(ID,{...f.body,confirmed:false},actor));assert.equal(f.sql.prepare("SELECT count(*) n FROM app_state WHERE key LIKE 'automatic_local_clone_v1:%'").get().n,1);
 const retried=await api.retryAutomaticClone(ID,f.body,actor),p=retried.request,old=savedRequest(f,original);assert.equal(retried.replayed,false);assert.notEqual(p.id,original.id);assert.equal(p.retry_of,original.id);assert.equal(p.owner_decision_id,f.body.owner_decision_id);assert.equal(p.status,'cost_check_pending');assert.equal(p.engine,null);assert.equal(p.provider_call_started,undefined);assert.equal(p.provider_result,undefined);assert.equal(p.quote,undefined);assert.deepEqual(p.base,original.base);assert.deepEqual(p.binding,original.binding);assert.equal(p.first_review_id,original.first_review_id);assert.equal(p.voice_id,original.voice_id);assert.equal(old.status,'superseded');assert.equal(old.superseded_by,p.id);assert.equal(old.provider_call_started,true);assert.equal(old.invocation_id,original.invocation_id);assert.deepEqual(old.quote,original.quote);assert.deepEqual(old.terminal_failure,original.terminal_failure);assert.equal((await api.readAutomaticClone(ID,actor)).request.id,p.id);assert.equal((await api.nextAutomaticClone()).automatic_clone.request_id,p.id);
 const replay=await api.retryAutomaticClone(ID,f.body,actor);assert.equal(replay.replayed,true);assert.equal(replay.request.id,p.id);assert.equal(f.sql.prepare("SELECT count(*) n FROM app_state WHERE key LIKE 'automatic_local_clone_v1:%'").get().n,2);assert.equal(f.sql.prepare("SELECT count(*) n FROM production_reviews WHERE decision='automatic_clone_owner_retry_v1'").get().n,1);await assert.rejects(()=>api.retryAutomaticClone(ID,{...f.body,owner_decision_id:'SYNTHETIC-another-confirmation'},actor));await assert.rejects(()=>api.blockAutomaticClone(ID,{request_id:old.id,version:old.version,reason:'must not reopen'},actor));await assert.rejects(()=>api.claimAutomaticClone(ID,{request_id:p.id,version:p.version,invocation_id:'SYNTHETIC-premature'},actor));
 const quoted=(await api.quoteAutomaticClone(ID,{request_id:p.id,version:p.version,quote:{...freshQuote(),saved_default_engine:'starfish'}},actor)).request;assert.equal(quoted.engine,'starfish','new request checks the currently saved default instead of inheriting the old failed engine');const c=await api.claimAutomaticClone(ID,{request_id:quoted.id,version:quoted.version,invocation_id:'SYNTHETIC-new-single-call'},actor),started=(await api.checkpointAutomaticClone(ID,{request_id:c.request.id,version:c.request.version,lease_token:c.lease_token,provider_call_started:true},actor)).request;await assert.rejects(()=>api.checkpointAutomaticClone(ID,{request_id:started.id,version:started.version,lease_token:c.lease_token,provider_call_started:true},actor));assert.equal((await api.recordAutomaticCloneAudio(ID,{request_id:started.id,version:started.version,lease_token:c.lease_token,invocation_id:started.invocation_id,result:providerAudio(started)},actor)).request.status,'audio_ready');assert.equal(f.protectedRows(),before);assert.deepEqual(f.sql.prepare("SELECT * FROM production_reviews WHERE decision='approve' ORDER BY id").all(),firstReviews);
});

