 const f=await first(t),{p,auth}=await started(f),failure=terminalFailure(p),body={request_id:p.id,version:p.version,failure};await assert.rejects(()=>api.recordAutomaticCloneTerminalFailure(ID,body,actor),e=>e.status===403);await assert.rejects(()=>api.recordAutomaticCloneTerminalFailure(ID,body,{trusted_owner_service:true}));const u=(await api.blockAutomaticClone(ID,{request_id:p.id,version:p.version,lease_token:auth.lease_token,reason:'SYNTHETIC ended with failed tool'},actor)).request,r=await api.recordAutomaticCloneTerminalFailure(ID,{...body,version:u.version},{trusted_owner_service:true});assert.equal(r.request.status,'provider_failed');const replay=await api.recordAutomaticCloneTerminalFailure(ID,{...body,version:u.version},{trusted_owner_service:true});assert.equal(replay.replayed,true);assert.equal(replay.request.version,r.request.version);await assert.rejects(()=>api.recordAutomaticCloneTerminalFailure(ID,{...body,version:r.request.version,failure:{...failure,response_sha256:'0'.repeat(64)}},{trusted_owner_service:true}));
