// Real dispatch/current/claim/return functions against isolated migrated SQLite
// and in-memory R2; only browser audio and renderer bytes are synthetic fixtures.
function dispatchConsumerCall(){const actions={automatic_clone_read:api.readAutomaticClone,automatic_clone_preflight:api.preflightAutomaticClone,automatic_clone_quote:api.quoteAutomaticClone,automatic_clone_claim:api.claimAutomaticClone,automatic_clone_checkpoint:api.checkpointAutomaticClone,automatic_clone_audio:api.recordAutomaticCloneAudio,automatic_clone_block:api.blockAutomaticClone};return async b=>{if(b.action==='read')return{job:await api.getJob(b.id)};if(b.action==='dispatch_next')return api.nextWork(undefined,b.exclude_job_ids||[]);if(b.action==='automatic_clone_read')return actions[b.action](b.id,actor);if(actions[b.action])return actions[b.action](b.id,b,actor);throw Error('SYNTHETIC unexpected action '+b.action)};}
async function uploadDispatchedClone(f,job,result){const source=(await api.readAutomaticClone(ID,actor)).request,video=Buffer.from(f.video);video[video.length-1]=5;const zip=Buffer.from('PK\x03\x04SYNTHETIC dispatched cloned project'),request=structuredClone(f.request);Object.assign(request,{request_id:'SYNTHETIC-dispatched-clone',automatic_clone_request_id:source.id,video:{...request.video,sha256:sha(video),file_name:'dispatched-clone.mp4'},project_archive:{...request.project_archive,sha256:sha(zip),size_bytes:zip.length,file_name:'dispatched-clone.zip'},project:{...request.project,file_sha256:'f'.repeat(64),render_receipt_sha256:'1'.repeat(64)},voice:{...request.voice,kind:'owner-cloned',owner_clone_used:true,audio_sha256:source.provider_result.audio_sha256}});request.qa.final_duration.file_sha256=sha(video);Object.assign(request.qa,{outro_version:'v6',outro_frames:119,outro_sha256:pin.sha256,outro_duration_seconds:119/30});request.qa.clone_sync={schema:'automatic-clone-sync-v1',base_video_sha256:f.request.video.sha256,audio_sha256:source.provider_result.audio_sha256,source_timeline_sha256:f.request.project.file_sha256,result_timeline_sha256:request.project.file_sha256,sync_map_sha256:'2'.repeat(64),original_outro_frames:119,original_outro_audio_sha256:'3'.repeat(64),result_outro_audio_sha256:'3'.repeat(64),normal_source_speed:true,old_narration_removed:true,music_gain_db:-15,caption_audio_sha256:source.provider_result.audio_sha256,full_decode:true};const p=(await api.beginLocalReviewDraft(ID,request,actor)).draft,next={...f,video,zip,request};await archive(next,p,'video',video);await archive(next,p,'project_archive',zip);const returned=await api.returnLocalReviewDraft(ID,{local_draft_id:p.local_draft_id},actor);return{...returned,status:'local-review-returned',local_draft_id:returned.draft.local_draft_id};}
for(const mode of ['auto','node'])test('real dispatch_next routes '+mode+' Studio request through consumer to actual second-review archive return',async t=>{const f=await first(t,{preview:true,mode}),call=dispatchConsumerCall(),selected=await call({action:'dispatch_next'});assert.equal(selected.kind,'automatic-clone');assert.equal(selected.job.review_mode,mode);assert.equal(selected.automatic_clone.request_id,f.state.request.id);let reads=0,previews=0,renders=0;const r=await runAutomaticClone(selected,{call,nativeVoice:{readEvidence:()=>{throw Error('API route forbidden')},generate:()=>{throw Error('API route forbidden')}},studioPreviewVoice:{readEvidence:async({job,request})=>{reads++;assert.equal(job.review_mode,mode);assert.equal(request.acquisition_method,'heygen_studio_audio_preview');assert.equal(job.media_continuation.current_id,request.scope_id);return{...freshQuote(),provider_tool:'heygen_studio_audio_preview'}},generate:async({request})=>{previews++;return previewResult(request)}},renderClone:async({job,request})=>{renders++;assert.equal(job.review_mode,mode);return{automatic_clone_request_id:request.id,owner_voice_used:true,voice_kind:'owner-cloned',new_paid_calls:0,quality_approved:false,qa:{clone_sync:{audio_sha256:request.provider_result.audio_sha256}}}},upload:(job,result)=>uploadDispatchedClone(f,job,result)});assert.equal(r.status,'automatic-clone-awaiting-second-review');assert.equal(reads,1);assert.equal(previews,1);assert.equal(renders,1);const after=await api.getJob(ID);assert.equal(after.review_mode,mode);assert.equal(api.automaticCloneProof(after).request.id,selected.automatic_clone.request_id);assert.equal(api.automaticCloneWarehouseAllowed(after),false);assert.equal((await api.readAutomaticClone(ID,actor)).clone.stage,'awaiting_second_review');assert.equal(after.publication_reports.length,0);});
