test('node mode without an explicit shared request is not silently promoted into automatic clone dispatch',async t=>{const f=await first(t,{mode:'node'}),selected=await api.nextWork();assert.notEqual(selected.kind,'automatic-clone');assert.equal((await api.readAutomaticClone(ID,actor)).clone.required,false);assert.equal(f.sql.prepare("SELECT count(*) n FROM app_state WHERE key LIKE 'automatic_local_clone_v1:%'").get().n,0);});
for(const mode of ['auto','node'])test('scope cancellation after '+mode+' dispatch prevents Studio preparation and retains original request',async t=>{const f=await first(t,{preview:true,mode}),call=dispatchConsumerCall(),selected=await api.nextWork();assert.equal(selected.kind,'automatic-clone');const before=JSON.stringify(savedRequest(f,f.state.request));f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify({id:'SYNTHETIC-cancelled-scope',scope:null}),'media_scope_v1:'+ID);let touches=0;const result=await runAutomaticClone(selected,{call,studioPreviewVoice:{readEvidence:()=>{touches++;throw Error('Must never open browser')}}});assert.equal(result.status,'automatic-clone-current-binding-changed');assert.equal(touches,0);assert.equal(JSON.stringify(savedRequest(f,f.state.request)),before);assert.equal(await api.nextAutomaticClone(),null);});

async function prepareFirstCoverOriginals(f){const a=ready(f),p=(await api.beginPostVideoPreparation(ID,{...beginBody(f.plan,a),aigc_covers:syntheticHostAigcCovers(f.plan,a.files)},actor)).plan;for(const role of Object.keys(a.files))await postArchive(f,p,role,a);const original=(await api.completePostVideoPreparation(ID,{plan_id:p.plan_id,expected_version:p.version},actor)).plan;f.originalCoverPlan=original;f.originalCoverAssets=a;return original;}
const reusedCoverBody=(p,a)=>({...beginBody(p,a),aigc_covers:{...p.cover_request.reuse_source.source_receipt,request_id:p.cover_request.request_id,plan_id:p.plan_id,job_id:p.job_id,binding:p.binding,video_sha256:p.base_video.sha256,reuse_source:p.cover_request.reuse_source}});
for(const mode of ['auto','node'])test(mode+' owner clone reuses exact confirmed original AIGC covers with honest old generation provenance and a new second-review package',async t=>{const f=await cloneReturned(t,prepareFirstCoverOriginals,{preview:true,mode}),source=f.plan.cover_request.reuse_source;assert.ok(source);assert.equal(source.source_plan_id,f.originalCoverPlan.plan_id);assert.equal(source.base_video_sha256,f.originalCoverPlan.base_video.sha256);assert.notEqual(f.plan.base_video.sha256,source.base_video_sha256);assert.equal(source.source_request.request_id,f.originalCoverPlan.cover_request.request_id);const a=ready(f),body=reusedCoverBody(f.plan,a);for(const c of body.aigc_covers.covers){assert.equal(c.host_artifact.request_id,source.source_request.request_id);assert.equal(c.host_artifact.video_sha256,source.base_video_sha256);assert.equal(c.sha256,a.files[c.role].sha256);}const p=(await api.beginPostVideoPreparation(ID,body,actor)).plan;for(const role of Object.keys(a.files))await postArchive(f,p,role,a);const completed=(await api.completePostVideoPreparation(ID,{plan_id:p.plan_id,expected_version:p.version},actor)).plan;assert.equal(completed.status,'prepared');assert.equal(completed.base_video.sha256,f.request.video.sha256);assert.equal(completed.aigc_covers.reuse_source.source_plan_id,source.source_plan_id);assert.equal((await api.readAutomaticClone(ID,actor)).clone.stage,'awaiting_second_review');assert.equal(api.automaticCloneWarehouseAllowed(await api.getJob(ID)),false);const approved=await api.approvePostVideoPreparation(ID,{plan_id:p.plan_id,expected_version:completed.version,confirmation:true},actor);assert.equal(api.automaticCloneSecondApproved(approved.job),true);assert.equal(api.completedProductionDelivery(approved.job),true);assert.equal(approved.job.publication_reports.length,0);});
