// These regressions exercise the real SQLite transaction guards. Their source
// digests are synthetic executor attestations, not independently verified chat,
// browser, provider or media evidence. They never call an external service.
import {STUDIO_EFFECT_CLAIM_MAX_AGE_MS,STUDIO_READY_PLAY_MAX_AGE_MS,studioCanonical} from '../lib/studio-preview-generation-contract.mts';
const domainRoot=r=>'studio_preview_generations_v1:'+ID+':'+r.id;
const domainRead=r=>ownerPolicy({action:'read',job_id:ID,request_id:r.id});
const domainHeaders=f=>policyRows(f).filter(row=>row.key.includes(':generation:'));
async function domainEffect(f,r,patch={}){
 const status=await domainRead(r),e=effectFor(f.registered.policy,{previous_generation_id:status.generation_summary.generation_id,previous_generation_evidence_sha256:status.generation_summary.evidence_sha256,previous_outcome:status.generation_summary.previous_outcome,...patch});
 const proof=await api.recordStudioPreviewCurrentEffect(ID,{request_id:r.id,request_version:r.version,effect:e},{trusted_owner_service:true});return{effect:e,proof};
}
async function domainClaimed(t){const f=await policyFixture(t),r=await unknownPolicyRequest(f),{effect,proof}=await domainEffect(f,r),claim=await generationClaim(f,r,proof);return{...f,r:savedRequest(f,r),effect,proof,claim};}
function domainEvent(f,event,data,patch={}){return api.recordStudioPreviewGenerationEvent(ID,{request_id:f.r.id,request_version:f.r.version,generation_id:f.claim.generation.generation_id,lease_token:f.claim.lease_token,event,data,...patch},{trusted_owner_service:true});}
function domainIntent(f,patch={}){const at=new Date(Math.max(Date.now(),Date.parse(f.claim.generation.created_at))).toISOString();return{intent_created_at:at,local_intent_sha256:'c'.repeat(64),source:'parent-before-preview',...patch};}
const domainObserved=(f,intent,patch={})=>({play_intent_sha256:intent.event_sha256,browser_attempt_id:'browser-22222222-2222-4222-8222-222222222222',browser_evidence_sha256:'e'.repeat(64),event_stream_sha256:'f'.repeat(64),lifecycle_sha256:'1'.repeat(64),ready_response_sha256:'a'.repeat(64),ready_code_sha256:'b'.repeat(64),ready_binding_sha256:sha(studioCanonical(f.claim.generation.binding)),ready_observed_at:new Date().toISOString(),editor_tab_sha256:'d'.repeat(64),ready_parent_accepted:true,clicked_at:new Date().toISOString(),play_clicked:true,...patch});
const domainAudio=(observed,patch={})=>({play_observed_sha256:observed.event_sha256,audio_sha256:'2'.repeat(64),audio_size_bytes:8000,duration_seconds:40,cache_metadata_sha256:'3'.repeat(64),provider_result_sha256:'4'.repeat(64),...patch});
const domainTerminal=(outcome='known-success',patch={})=>({outcome,source_sha256:'5'.repeat(64),cleanup_confirmed:true,editor_released:true,active_call:false,...patch});
async function domainSuccess(f){const intent=await domainEvent(f,'play-intent',domainIntent(f)),observed=await domainEvent(f,'play-observed',domainObserved(f,intent)),audio=await domainEvent(f,'audio-result',domainAudio(observed)),terminal=await domainEvent(f,'terminal',domainTerminal());return{intent,observed,audio,terminal};}
async function withDomainClock(now,fn){const original=Date.now;Date.now=()=>now;try{return await fn();}finally{Date.now=original;}}

