test('owner approval reads the archive once, while a later replay still detects changed bytes',async t=>{
 const f=await preparedClone(t,{resultsOnly:true}),sid=f.plan.archives.complete_bundle,r2=globalThis.__localReviewR2,original=r2.get,body={plan_id:f.plan.plan_id,expected_version:f.plan.version,confirmation:true};let reads=0,key='';
 r2.get=async k=>{if(k.includes(sid)&&k.endsWith('/part-000')){reads++;key=k;}return original(k);};
 try{const accepted=await api.approvePostVideoPreparation(ID,body,actor);assert.equal(accepted.replayed,false);assert.equal(accepted.job.status,'completed');assert.equal(reads,1,'one full read in the initial approval, no redundant second read');assert.ok(key);const saved=f.map.get(key),damaged=Buffer.from(saved.bytes);damaged[damaged.length-1]^=1;f.map.set(key,{...saved,bytes:damaged});await assert.rejects(()=>api.approvePostVideoPreparation(ID,body,actor),/完整性|真实|变化/);assert.equal(reads,2,'a later independent replay still rechecks actual bytes');}finally{r2.get=original;}
});
